            print("User added successfully")
        elif choice == "2":
            user = input("Enter user name :")
            color = input("Enter user color :")
            if accessControlSystem.checkAccess(user , color):
                print("Access granted")
            else:
                print("Access denied")
        elif choice == "3":
            break
        else:
            print("Invalid choice")
    print("Exiting program")
    accessControlSystem.exit()

if __name__ == "__main__":
    main()
